Use `iterdir()`:

```python
from pathlib import Path

for item in Path('.').iterdir():
    print(item)

# Filter for files only
for file in Path('.').iterdir():
    if file.is_file():
        print(file)

# Filter for directories
for directory in Path('.').iterdir():
    if directory.is_dir():
        print(directory)
```

For more control, combine with `glob()` to find specific file types.

Use `@functools.wraps` in decorators:

```python
import functools

def my_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print('Function called')
        return func(*args, **kwargs)
    return wrapper

@my_decorator
def greet(name):
    """Greet someone."""
    return f'Hello, {name}!'

print(greet.__name__)  # 'greet' (not 'wrapper')
print(greet.__doc__)  # 'Greet someone.'
```

Without `@functools.wraps`, metadata is lost.

Use `@functools.cache` (Python 3.9+):

```python
from functools import cache

@cache
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(100))  # Fast with caching
```

This is equivalent to `@lru_cache(maxsize=None)` but simpler. Works only with hashable arguments.

Use `List[T]` and `Dict[K, V]`:

```python
from typing import List, Dict

def process_numbers(numbers: List[int]) -> int:
    return sum(numbers)

def create_mapping(keys: List[str], values: List[int]) -> Dict[str, int]:
    return dict(zip(keys, values))

result = create_mapping(['a', 'b', 'c'], [1, 2, 3])
print(result)  # {'a': 1, 'b': 2, 'c': 3}
```

Python 3.9+ allows using `list[int]` and `dict[str, int]` directly.

Use `Protocol` to define structural types:

```python
from typing import Protocol

class Drawable(Protocol):
    def draw(self) -> None: ...

def render(obj: Drawable) -> None:
    obj.draw()

class Circle:
    def draw(self) -> None:
        print('Drawing circle')

render(Circle())  # Works without explicit inheritance
```

Useful for duck typing with type safety.

Use nested generic types:

```python
from typing import Dict, List, Tuple

def process(data: Dict[str, List[int]]) -> Tuple[str, float]:
    result = {}
    for key, values in data.items():
        result[key] = sum(values) / len(values)
    return 'success', list(result.values())[0]

data = {'scores': [100, 95, 87, 92]}
print(process(data))
```

With Optional:

```python
from typing import Optional, List

def find_user(name: str) -> Optional[Dict[str, str]]:
    users = [{'name': 'Alice', 'age': '30'}]
    for user in users:
        if user['name'] == name:
            return user
    return None
```

Use `jsonschema` library:

```python
from jsonschema import validate, ValidationError
import json

schema = {
    'type': 'object',
    'properties': {
        'name': {'type': 'string'},
        'age': {'type': 'integer', 'minimum': 0}
    },
    'required': ['name']
}

data = {'name': 'Alice', 'age': 30}

try:
    validate(instance=data, schema=schema)
    print('Valid')
except ValidationError as e:
    print(f'Invalid: {e.message}')
```

Check keys before processing:

```python
import json
from pathlib import Path

required_keys = {'name', 'email', 'age'}

data = json.loads(Path('data.json').read_text())

if isinstance(data, dict):
    if required_keys.issubset(data.keys()):
        print('Valid')
    else:
        missing = required_keys - set(data.keys())
        print(f'Missing keys: {missing}')
```

Or use schema validation:

```python
from jsonschema import validate

schema = {
    'type': 'object',
    'properties': {
        'name': {'type': 'string'},
        'email': {'type': 'string'},
        'age': {'type': 'integer'}
    },
    'required': ['name', 'email', 'age']
}

validate(instance=data, schema=schema)
print('Valid')
```

Use `isinstance()` for runtime type checking:

```python
value = 42

if isinstance(value, int):
    print('Integer')
elif isinstance(value, str):
    print('String')

# Check multiple types
if isinstance(value, (int, float)):
    print('Numeric')
```

With type hints:

```python
from typing import Union

def process(value: Union[int, str]) -> None:
    if isinstance(value, int):
        print(f'Integer: {value}')
    else:
        print(f'String: {value}')
```

Use tuple of exception types:

```python
try:
    value = int('not a number')
except (ValueError, TypeError) as e:
    print(f'Error: {e}')

try:
    with open('missing.txt') as f:
        data = f.read()
except (FileNotFoundError, IOError) as e:
    print(f'File error: {e}')
```

With different handling:

```python
try:
    operation()
except ValueError as e:
    print(f'Invalid value: {e}')
except TypeError as e:
    print(f'Invalid type: {e}')
except Exception as e:
